  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\" // Switch to \"mysql\" or \"sqlserver\" if need\n  url      = env(\"DATABASE_URL\")\n}\n\n// Role enum for high-level categorization\nenum Role {\n  USER\n  ADMIN\n  MANAGER\n  STAFF\n  SUPER_ADMIN\n  VENDOR\n}\n\n// Module define major application areas\nenum AppModule {\n  DASHBOARD\n  PROCUREMENT\n  INVENTORY\n  FINANCE\n  SALES\n  HR\n  SETTINGS\n  VENDOR_PORTAL\n}\n\n// Actions define what can be done within a module\nenum Action {\n  READ\n  CREATE\n  UPDATE\n  DELETE\n  APPROVE\n  EXPORT\n  MANAGE // Full access\n}\n\nmodel User {\n  id        Int     @id @default(autoincrement())\n  email     String  @unique\n  username  String? @unique\n  password  String?\n  firstName String?\n  lastName  String?\n  picture   String?\n\n  // Basic classification\n  role   Role   @default(USER)\n  status Status @default(ACTIVE)\n\n  // Advanced granular permissions\n  permissions Permission[]\n\n  isEmailVerified Boolean   @default(false)\n  googleId        String?   @unique\n  lastLoginAt     DateTime?\n  loginAttempts   Int       @default(0)\n\n  refreshTokens RefreshToken[]\n  companies     UserCompany[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"users\")\n}\n\n// Stores explicit permissions for a user\n// Example: User A can [READ, APPROVE] on [FINANCE] module\nmodel Permission {\n  id      Int       @id @default(autoincrement())\n  userId  Int\n  module  AppModule\n  actions Action[] // Array of allowed actions, e.g. [READ, CREATE]\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, module]) // One permission entry per module per user to keep it clean\n  @@map(\"permissions\")\n}\n\nmodel RefreshToken {\n  id         Int      @id @default(autoincrement())\n  token      String   @unique\n  userId     Int\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt  DateTime\n  revoked    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  replacedBy String?\n\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\n// Enterprise Core Models\n\nmodel Company {\n  id       Int     @id @default(autoincrement())\n  code     String  @unique // Code for login/identification (e.g., \"CORP001\")\n  name     String\n  address  String?\n  phone    String?\n  email    String?\n  website  String?\n  logo     String?\n  isActive Boolean @default(true)\n\n  // Relations\n  users     UserCompany[]\n  suppliers Supplier[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"companies\")\n}\n\nmodel UserCompany {\n  id         Int     @id @default(autoincrement())\n  userId     Int\n  companyId  Int\n  supplierId Int? // Optional: Only populated if the user is a Supplier/Vendor\n  role       Role    @default(USER)\n  isDefault  Boolean @default(false)\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  company  Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  supplier Supplier? @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, companyId])\n  @@index([userId])\n  @@index([companyId])\n  @@index([supplierId])\n  @@map(\"user_companies\")\n}\n\nmodel Supplier {\n  id        Int    @id @default(autoincrement())\n  companyId Int\n  code      String // Vendor Code\n  name      String\n\n  // Relations\n  userAccess UserCompany[] // Users who can access this supplier portal\n\n  // Contact Info\n  contactPerson String?\n  email         String?\n  phone         String?\n  mobile        String?\n  address       String?\n  city          String?\n  state         String?\n  country       String?\n  zipCode       String?\n\n  // Financial & Logic\n  taxId         String? // NPWP\n  currency      String  @default(\"IDR\")\n  termOfPayment Int     @default(0) // Days\n  creditLimit   Decimal @default(0) @db.Decimal(15, 2)\n  isActive      Boolean @default(true)\n  notes         String?\n\n  company Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, code])\n  @@index([companyId])\n  @@map(\"suppliers\")\n}\n\nenum Status {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  BANNED\n}\n",
